-- Optional Oracle 12c+ fixture for identity-column compatibility.
-- Verifies that generated ISEQ$$_... sequences are not exported as standalone objects.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_IDENTITY_PARENT CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

CREATE TABLE OC_IDENTITY_PARENT (
  IDENTITY_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
  DISPLAY_NAME VARCHAR2(80) NOT NULL,
  CREATED_AT DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT OC_IDENTITY_PARENT_PK PRIMARY KEY (IDENTITY_ID)
);

COMMENT ON TABLE OC_IDENTITY_PARENT IS '12c identity column fixture for oracode';

PROMPT Optional 12c identity fixture loaded
